import * as React from "react";

export type RecordDotIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function RecordDotIcon({ size = 20, ...props }: RecordDotIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="12" r="8.5" /><circle cx="12" cy="12" r="3.5" />
    </svg>
  );
}
